var _Duracion = DATEDIFF(vwSGJEntradaExpedientesBO[AsignacionJuez],vwSGJEntradaExpedientesBO[FechaSalida],DAY)
var _Invalido = ISBLANK(vwSGJEntradaExpedientesBO[AsignacionJuez]) || _Duracion<0

return

if(_Invalido, BLANK(), _Duracion)

VAR _Instancia = RELATED ( 'Dim_Instancia'[Instancia] )
VAR _TipoFallo = RELATED ( 'Tipo Falloo Salida'[TipoFallo] )
VAR _Acoge = RELATED ( 'Tipo Falloo Salida'[Acoge] )
VAR _Asunto = RELATED ( vwSGJAsuntos[Asunto] )
VAR _FallosNuncaFinalizan = {"Rebeldía", "Asignacion Sala", "Confirma", "Garantía Económica, y Presentarse Periódicamente Ante el Juez", "Intimacion", "Levantamiento de Rebeldía", "Admisible", "No Comparecencia", "Fijar Audiencia", "Inhibición", "No Aplica", "Modifica", "Confirma" }
VAR _AcuerdosFin = {"ARCHIVO DEFINITIVO", "ARCHIVO PROVISIONAL", "EXTINCIÓN POR APLICACIÓN DE CRITERIO DE OPORTUNIDAD", "EXTINCIÓN POR RESARCIMIENTO INTEGRAL DEL DAÑO", "PERDON JUDICIAL", "SUSPENSIÓN CONDICIONAL DE LA PENA", "PROCEDIMIENTO PENAL ABREVIADO", "SUSPENSIÓN CONDICIONAL DEL PROCEDIMIENTO", "SUSPENSIÓN CONDICIONAL DEL PROCESO", "CRITERIO DE OPORTUNIDAD", "ACUERDO PLENO", "CONCILIACIÓN" }
VAR _AsuntosFin = {"ACCIÓN PENAL PÚBLICA"}
VAR _AsuntosFinDependeFallo = {"EXTINCIÓN DE CONTRATO", "DECLARATORIA DE EXTINCIÓN", "EXTINCIÓN", "EXTINCIÓN POR PRESCRIPCIÓN DE MULTA", "EXTINCIÓN DE LA PENA/SANCIÓN", "EXTINCIÓN DE LA ACCIÓN PENAL", "EXTINCIÓN POR PRESCRIPCIÓN DE MULTA", "EXTINCIÓN DE LA PENA POR MUERTE DEL PENADO", "EXTINCIÓN POR PRESCRIPCIÓN DE LA PENA POR VENCIMIENTO DE PLAZO MÁXIMO", "EXTINCIÓN DE LA PENA POR AMNISTIA", "SOLICITUD EXTINCIÓN DE LA ACCIÓN PENAL"}
VAR _OrdenesLibertad = {"ORDEN DE LIBERTAD POR EXTINCIÓN DE LA PENA", "ORDEN DE LIBERTAD", "MANDAMIENTO DE LIBERTAD POR CUMPLIMIENTO DE PENA", "ORDEN DE LIBERTAD POR CUMPLIMIENTO DE PENA", "AUTORIZACIÓN DE LIBERTAD", "ORDEN DE LIBERTAD POR EXTINCIÓN DE LA PENA"}
VAR _FallosFin = {"Condena", "Condena / Absuelve", "Absuelve", "Retiro de acusación", "Extinción por resarcimiento integral del daño", "Extinción por aplicación de Criterio de Oportunidad", "Extinción por Desistimiento", "Extinción por Vencimiento Plazo", "Extinción por Prescripción", "Extinción por fallecimiento del imputado", "Extinción", "Auto de apertura a juicio", "Apertura a Juicio / No Ha Lugar", "Apertura a Juicio", "No Ha Lugar"}

RETURN
IF( NOT RELATED('vwSGJMaterias'[Materia (grupos)]) = "PENAL" && NOT RELATED(Dim_Tipo_Tribunal[Materia Tribunal]) = "PENAL", BLANK(),
    SWITCH ( TRUE(),
        [Acuerdo] IN _AcuerdosFin, [Acuerdo],
        _Instancia = "EJECUCIÓN" && _Asunto IN _OrdenesLibertad && _Acoge = TRUE(), "ORDEN DE LIBERTAD",
        _TipoFallo IN _FallosFin, UPPER ( _TipoFallo ),
        _Asunto IN _AsuntosFinDependeFallo && _Acoge = TRUE() && NOT ( _TipoFallo IN _FallosNuncaFinalizan), _Asunto,
        _Asunto IN _AsuntosFin && NOT ISBLANK( vwSGJEntradaExpedientesBO[FechaSalida] ) && NOT ( _TipoFallo IN _FallosNuncaFinalizan ), _Asunto,
        BLANK()
    )
)

IF(
    CALCULATE(
        COUNTROWS(vwSGJProductos),
        vwSGJProductos[IdTipoFallo] in {62,39})>0 ||
        CALCULATE(COUNTROWS('Penal_vwTramiteParteDecisiones_sj'),
        'Penal_vwTramiteParteDecisiones_sj'[IdTipoFallo] in {62,39}
    )>0, "Si", "No"
)

IF ( NOT vwSGJCasos[MaxEtapa] IN {"1- PREPARATORIA"},
    BLANK(),
    COALESCE(
        MINX (
            TOPN( 1,
                CALCULATETABLE(
                    vwSGJEntradaExpedientesBO,
                    TREATAS ( {1,2}, vwSGJEntradaExpedientesBO[IdTipoProcedimiento2] ),
                    vwSGJEntradaExpedientesBO[Etapa] IN {"1- PREPARATORIA"},
                    dvwTribunalesBO[IdCategoriaTribunal] IN {3,4}
                ),
                vwSGJEntradaExpedientesBO[OrdenTramite],
                DESC
            ),
            vwSGJEntradaExpedientesBO[IdSala3]
        ),
        CALCULATE (
            MIN ( vwSGJEntradaExpedientesBO[IdSala3] )
        )
    )
)

measures.expression:
var _cantidad = CALCULATE([Audiencias Programadas],vwSGJAudienciasBO[IntervaloFijacion]<=15)
return
DIVIDE(_cantidad,[Audiencias Programadas],0)

DIVIDE(
    CALCULATE([Entrada Trámites],
        KEEPFILTERS(vwSGJAsuntos[Asunto (origen)] in {"OTROS", "Otras Solicitudes"}
        )
    ),
    [Entrada Trámites],
    0
)

var _Solucion = DIVIDE([Juez Salida],[Juez Entrada],1)
Var _Caso1 = AND([Juez Entrada]>0,[Juez Salida]<1)

return

if(_Caso1,0,_Solucion)

SWITCH( TRUE(),
    [% Solución (Finalizados)] >= (DIVIDE(SELECTEDVALUE(Rangos[Value]),100)),1,0
)

VAR _T =
FILTER(
    SUMMARIZECOLUMNS(
        'dvwSalasBO'[IdSala],
        'dvwSalasBO'[Sala],
        "E", CALCULATE( [Entrada Trámites], CROSSFILTER( Fechas[Fechas], vwSGJEntradaExpedientesBO[Fecha Entrada], None ), vwSGJEntradaExpedientesBO[Fecha Entrada] >= DATE(2022,09,01)),
        "S", IGNORE ( [Juez En Mora] )
    ), [S] < 1 && NOT dvwSalasBO[IdSala] IN {0, BLANK()}
)
RETURN
CALCULATE(
    COUNTROWS (_T)
)

VAR _T =
FILTER(
    SUMMARIZECOLUMNS(
        'dvwSalasBO'[IdSala],
        'dvwSalasBO'[Sala],
        "E", CALCULATE( [Entrada Trámites], CROSSFILTER( Fechas[Fechas], vwSGJEntradaExpedientesBO[Fecha Entrada], None ), vwSGJEntradaExpedientesBO[Fecha Entrada] >= DATE(2022,09,01)),
        "S", IGNORE ( [Juez En Mora] )
    ), [S] > 0 && NOT dvwSalasBO[IdSala] IN {0, BLANK()}
)
RETURN
CALCULATE(
    COUNTROWS (_T)
)

CALCULATE(
    DISTINCTCOUNT( vwSGJCasos[IdCaso] ),
    CALCULATETABLE(
        FILTER(
            vwSGJEntradaExpedientesBO,
            NOT ISBLANK( vwSGJEntradaExpedientesBO[Acuerdo] ) || RELATED( vwSGJAsuntos[Asunto (origen)] ) IN {"ARCHIVO DEFINITIVO", "ARCHIVO PROVISIONAL", "SUSPENSIÓN CONDICIONAL DE LA PENA", "PROCEDIMIENTO PENAL ABREVIADO", "SUSPENSIÓN CONDICIONAL DEL PROCEDIMIENTO", "CRITERIO DE OPORTUNIDAD"}
        ),
        TREATAS( {1,2}, vwSGJEntradaExpedientesBO[IdTipoProcedimiento2] ),
        CROSSFILTER( vwSGJCasos[IdCaso], vwSGJEntradaExpedientesBO[IdCaso], Both),
        CROSSFILTER( 'Penal_vwTramiteInfracciones_sj'[IdTramite], vwSGJEntradaExpedientesBO[IdTramite], None)
    ),
    TREATAS( VALUES('Penal_vwInfracciones_gp'[IdInfraccion]), vwSGJCasos[IdInfraccionMayorPena] )
)

VAR _Fallos = {"Extinción","Extinción por aplicación de Criterio de Oportunidad","Extinción por Desistimiento","Extinción por fallecimiento del imputado","Extinción por Prescripción","Extinción por resarcimiento integral del daño","Extinción por Vencimiento Plazo","Perención","PERIMIDA"}
RETURN
DIVIDE(
    CALCULATE(
        [Salida Casos],
        KEEPFILTERS ( vwSGJTipoProcedimiento[Tipo Procedimiento] IN {"GRACIOSO", "CONTENCIOSO" } ),
        KEEPFILTERS( 'Tipo Falloo Salida'[TipoFallo] IN _Fallos )
    ),
    [Salida Casos]
)

CALCULATE(
    SELECTEDVALUE (
        UsuariosAcceso[NombreCompleto],
        IF ( ISFILTERED ( UsuariosAcceso ),
            "Más de un usuario seleccionado",
            "Sin usuario seleccionado"
        )
    )
)

COUNTROWS (
    FILTER (
        SUMMARIZECOLUMNS (
            UsuariosPortal[IdUsuarioPortal],
            "A", [Usuarios Portal Validados],
            "B", IGNORE ( CALCULATE ( [Entrada Trámites], ALLEXCEPT( vwSGJEntradaExpedientesBO, UsuariosPortal ) ) )
        ),
        ISBLANK ( [B] )
    )
)

COUNTROWS (
    FILTER (
        SUMMARIZECOLUMNS (
            UsuariosPortal[IdUsuarioPortal],
            "A", [Usuarios Portal Validados],
            "B", IGNORE ( CALCULATE ( [Entrada Trámites], ALLEXCEPT( vwSGJEntradaExpedientesBO, UsuariosPortal, dvwTribunalesBO[DepartamentoJudicial], dvwTribunalesBO[Distrito Judicial] ) ) )
        ),
        NOT ISBLANK ( [B] )
    )
)

MINX (
    CALCULATETABLE (
        SUMMARIZECOLUMNS (
            vwSGJEntradaExpedientesBO[IdTramite],
            "E", [Juez Estado Fallo],
            "F",
                IGNORE (
                    CALCULATE (
                        MAX ( vwSGJAudienciasBO[FechaAudiencia] ),
                        KEEPFILTERS ( vwSGJTipoAudiencias[TipoAudiencia] IN {"Lectura de fallo", "Lectura de Sentencia Integra", "Lectura íntegra de sentencia" } )
                    )
                )
        )
    ),
    [F]
)

COUNTROWS(
    CALCULATETABLE(
        'GD TramiteSubprocesoHistorial',
        KEEPFILTERS( 'GD TramiteSubprocesoHistorial'[Activo] = TRUE() ),
        CROSSFILTER( Fechas[Fechas], vwSGJEntradaExpedientesBO[Fecha Entrada], None ),
        FILTER( 'GD TramiteSubprocesoHistorial',
            NOT ISBLANK( RELATED(vwSGJEntradaExpedientesBO[AsignacionJuez] ) )
        )
    )
)
